// Browser half of the Kairosoft onsen theme.
// Generated by scripts/build.mjs, which fills in the token map and the
// stylesheet before the file is written.
window.__ModuleLoader__.load({
  id: 'dsh-kairosoft-theme',
  factory() {
    const THEME_PACK = __TOKEN_TABLE__;
    const CSS_TEXT = __CSS_TEXT__;
    // `null` is a real option: the theme is turned off and the built-in
    // palette comes back, so it needs a name that cannot collide with a theme id.
    const NATIVE = null;

    const STORAGE_KEY = 'kairosoft-theme:settings';
    const THEME_IDS = Object.keys(THEME_PACK);
    const DEFAULTS = {
      theme: THEME_IDS[0],
      artwork: true,
      panel: 84,
      sidebar: 80,
      focus: 38,
      linkSidebar: true,
      softShadow: false,
    };

    // Tokens whose alpha is a pane opacity the user may tune. Everything else
    // (text, borders, shadows) keeps its designed value.
    const PANE_TOKENS = {
      '--dsw-alias-bg-base': 'panel',
      '--dsw-alias-bg-layer-1': 'panel',
      '--dsw-alias-bg-layer-2': 'panel',
      '--dsw-alias-markdown-code-block': 'panel',
      '--dsw-specific-sidebar-fill': 'sidebar',
    };
    const PANE_BASE = { panel: 84, sidebar: 80 };

    const readSettings = () => {
      try {
        return { ...DEFAULTS, ...JSON.parse(window.localStorage.getItem(STORAGE_KEY) || '{}') };
      } catch {
        return { ...DEFAULTS };
      }
    };
    const writeSettings = (value) => {
      try {
        window.localStorage.setItem(STORAGE_KEY, JSON.stringify(value));
      } catch {
        /* private mode: keep the in-memory value */
      }
    };

    const shiftAlpha = (color, delta) => {
      const match = /^rgba\(([^,]+),\s*([^,]+),\s*([^,]+),\s*([\d.]+)\)$/.exec(color);
      if (!match) return color;
      const alpha = Math.min(0.99, Math.max(0.25, Number(match[4]) + delta));
      return `rgba(${match[1]}, ${match[2]}, ${match[3]}, ${Math.round(alpha * 100) / 100})`;
    };

    const tokensFor = (settings) => {
      const pack = THEME_PACK[settings.theme];
      if (!pack) return {};
      const BASE_TOKENS = pack.tokens;
      const panelDelta = (settings.panel - PANE_BASE.panel) / 100;
      const sideDelta = (settings.sidebar - PANE_BASE.sidebar) / 100;
      const shiftPair = (pair, delta) => ({
        light: shiftAlpha(pair.light, delta),
        dark: shiftAlpha(pair.dark, delta),
      });

      const out = {};
      const base = shiftPair(BASE_TOKENS['--dsw-alias-bg-base'], panelDelta);
      for (const [name, pair] of Object.entries(BASE_TOKENS)) {
        const role = PANE_TOKENS[name];
        if (!role) {
          out[name] = pair;
        } else if (role === 'panel') {
          out[name] = shiftPair(pair, panelDelta);
        } else if (settings.linkSidebar) {
          // The sidebar sits on a darker token of its own; when the user asks it
          // to match the main area, hand it the exact same value instead.
          out[name] = base;
        } else {
          out[name] = shiftPair(pair, sideDelta);
        }
      }
      return out;
    };

    // The panel paints itself with --kf-* values handed to it by syncPanelColors,
    // so it never has to guess what a DS alias means in this release.
    const PANEL_CSS = [
      '.kf-fab{position:fixed;right:16px;bottom:56px;width:34px;height:34px;',
      'display:flex;align-items:center;justify-content:center;padding:0;cursor:pointer;z-index:2147482000;',
      'border:1px solid var(--kf-line,rgba(0,0,0,.16));border-radius:8px;',
      'background:var(--kf-panel,#FCF7EA);color:var(--kf-accent,#AE4C18);',
      'box-shadow:0 2px 0 rgba(0,0,0,.18);opacity:.62;transition:opacity .15s}',
      '.kf-fab:hover{opacity:1}',
      '.kf-fab svg{width:18px;height:18px;display:block}',
      '.kf-sheet{position:fixed;right:16px;bottom:100px;width:264px;z-index:2147482001;',
      'padding:14px 14px 10px;border:1px solid var(--kf-line,rgba(0,0,0,.16));border-radius:8px;',
      'background:var(--kf-panel,#FCF7EA);color:var(--kf-text,#392D23);',
      'box-shadow:0 4px 0 rgba(0,0,0,.2);font:12px/1.5 system-ui,"Microsoft YaHei",sans-serif}',
      '.kf-sheet[hidden]{display:none}',
      '.kf-sheet h2{margin:0 0 2px;font-size:13px;font-weight:600;display:flex;align-items:center;justify-content:space-between}',
      '.kf-sheet .kf-sub{margin:0 0 12px;font-size:11px;color:var(--kf-muted,#7A654B)}',
      '.kf-row{display:block;margin:0 0 12px}',
      '.kf-row .kf-head{display:flex;justify-content:space-between;margin-bottom:5px}',
      '.kf-row output{font-variant-numeric:tabular-nums;color:var(--kf-muted,#7A654B)}',
      '.kf-row input[type=range]{width:100%;accent-color:var(--kf-accent,#AE4C18);margin:0}',
      '.kf-check{display:flex;align-items:center;gap:8px;margin:0 0 12px}',
      '.kf-check input{accent-color:var(--kf-accent,#AE4C18)}',
      '.kf-themes{display:flex;gap:6px;margin:0 0 12px}',
      '.kf-theme,.kf-mode{flex:1;padding:5px 4px;border-radius:5px;cursor:pointer;font:inherit;font-size:11px;',
      'border:1px solid var(--kf-line,rgba(0,0,0,.16));background:transparent;color:var(--kf-text,#392D23)}',
      '.kf-theme:hover,.kf-mode:hover{background:var(--kf-raised,rgba(0,0,0,.05))}',
      '.kf-theme[aria-pressed="true"],.kf-mode[aria-pressed="true"]{background:var(--kf-accent,#AE4C18);',
      'border-color:transparent;color:var(--kf-on-accent,#FFF6E2);font-weight:600}',
      '.kf-label{margin:0 0 6px;font-size:11px;color:var(--kf-muted,#7A654B)}',
      '.kf-foot{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--kf-line,rgba(0,0,0,.16));padding-top:9px;margin-top:2px}',
      '.kf-foot button{font:inherit;cursor:pointer;border-radius:4px;padding:4px 9px;border:1px solid var(--kf-line,rgba(0,0,0,.16));background:transparent;color:var(--kf-text,#392D23)}',
      '.kf-foot button:hover{background:var(--kf-raised,rgba(0,0,0,.05))}',
      '.kf-sheet .kf-close{border:0;background:transparent;color:inherit;cursor:pointer;font-size:15px;line-height:1;padding:2px 4px}',
      // Flatten the soft elevation shadows (and the sidebar's scroll fade) so
      // translucent panes do not show a blurred smudge behind them.
      'html[data-kairosoft-shadow="off"] body,html[data-kairosoft-shadow="off"] body *{',
      '--dsw-elevation-panel:var(--dsw-elevation-stroke);',
      '--dsw-elevation-prominent:var(--dsw-elevation-stroke);',
      '--dsw-elevation-soft:var(--dsw-elevation-stroke)}',
      'html[data-kairosoft-shadow="off"] [class*="_scrollFade"]{background:none!important}',
    ].join('');

    const LANTERN = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9.6 6.2V5a2.4 2.4 0 0 1 4.8 0v1.2" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/><rect x="8.4" y="5.6" width="7.2" height="1.6" rx=".8" fill="currentColor"/><rect x="7.8" y="7.2" width="8.4" height="9.6" rx="2" fill="currentColor" opacity=".18"/><rect x="7.8" y="7.2" width="8.4" height="9.6" rx="2" fill="none" stroke="currentColor" stroke-width="1.4"/><path d="M7.8 10.4h8.4M7.8 13.6h8.4" stroke="currentColor" stroke-width="1" opacity=".55"/><rect x="8.4" y="16.8" width="7.2" height="1.6" rx=".8" fill="currentColor"/><path d="M12 18.4v1.6" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>';

    const el = (tag, props, children) => {
      const node = document.createElement(tag);
      for (const [key, value] of Object.entries(props || {})) {
        if (key === 'text') node.textContent = value;
        else if (key === 'html') node.innerHTML = value;
        else if (key === 'className') node.className = value;
        else if (key.startsWith('on')) node.addEventListener(key.slice(2), value);
        else node.setAttribute(key, value);
      }
      for (const child of children || []) node.append(child);
      return node;
    };

    const mount = (ctx) => {
      const settings = readSettings();
      const root = document.documentElement;
      let disposeTokens = null;
      let style = null;

      const syncArtwork = () => {
        const pack = THEME_PACK[settings.theme];
        if (pack) root.style.setProperty('--kairosoft-artwork', pack.artwork);
        const shown = Boolean(pack && settings.artwork);
        root.style.setProperty('--kairosoft-art-image', shown ? 'var(--kairosoft-artwork)' : 'none');
        root.style.setProperty('--kairosoft-art-position', `${settings.focus}%`);
        syncCaption();
      };

      // The window controls sit in a strip the shell paints itself, taking its
      // colour from a hidden probe that reads the sidebar token. Any flat colour
      // there reads as a bar pasted over the picture, so hand the probe a fully
      // transparent colour: the strip then shows the page — and the artwork —
      // underneath, exactly like the panes below it.
      const syncCaption = () => {
        if (!settings.artwork || !THEME_PACK[settings.theme]) {
          root.style.removeProperty('--kairosoft-caption');
          return;
        }
        const next = 'rgba(0, 0, 0, 0)';
        if (root.style.getPropertyValue('--kairosoft-caption') === next) return;
        root.style.setProperty('--kairosoft-caption', next);
        // The shell only re-reads its probe when the document head mutates.
        const head = document.head;
        if (!head) return;
        const pulse = document.createComment('kairosoft-caption');
        head.append(pulse);
        pulse.remove();
      };

      const syncTitlebar = () => {
        let height = 0;
        const overlay = typeof navigator !== 'undefined' ? navigator.windowControlsOverlay : null;
        if (overlay && overlay.visible) {
          try {
            height = overlay.getTitlebarAreaRect().height;
          } catch {
            height = 0;
          }
        }
        if (!height && typeof getComputedStyle === 'function') {
          const declared = getComputedStyle(root).getPropertyValue('--dsh-windows-titlebar-height').trim();
          if (declared.endsWith('px')) height = Number.parseFloat(declared) || 0;
        }
        root.style.setProperty('--kairosoft-titlebar', `${Math.round(height)}px`);
        syncCaption();
      };

      const syncTokens = () => {
        if (disposeTokens) disposeTokens();
        disposeTokens = null;
        const pack = THEME_PACK[settings.theme];
        if (!pack) {
          // Built-in palette: drop our overrides so the app's own tokens win.
          root.style.removeProperty('--kairosoft-page-bg');
          root.style.removeProperty('--kairosoft-page-bg-dark');
          return;
        }
        disposeTokens = ctx.theme.overrideTokens('dsh-kairosoft-theme', tokensFor(settings));
        root.style.setProperty('--kairosoft-page-bg', pack.page.light);
        root.style.setProperty('--kairosoft-page-bg-dark', pack.page.dark);
      };

      const syncAll = () => {
        syncArtwork();
        syncTokens();
        syncShadow();
      };

      // Soft blurred elevation shadows and the sidebar's bottom fade both read
      // as smudges once the panes turn translucent, so they are opt-in.
      const syncShadow = () => {
        if (settings.softShadow) root.dataset.kairosoftShadow = 'on';
        else root.dataset.kairosoftShadow = 'off';
      };
      ctx.effect(() => {
        style = document.createElement('style');
        style.dataset.kairosoftTheme = '';
        style.textContent = CSS_TEXT + PANEL_CSS;
        document.head.append(style);
        syncAll();
        syncTitlebar();
        const remeasure = () => syncTitlebar();
        window.addEventListener('resize', remeasure);
        const overlay = typeof navigator !== 'undefined' ? navigator.windowControlsOverlay : null;
        if (overlay && typeof overlay.addEventListener === 'function') {
          overlay.addEventListener('geometrychange', remeasure);
        }
        return () => {
          if (disposeTokens) disposeTokens();
          disposeTokens = null;
          style?.remove();
          style = null;
          window.removeEventListener('resize', remeasure);
          if (overlay && typeof overlay.removeEventListener === 'function') {
            overlay.removeEventListener('geometrychange', remeasure);
          }
        };
      }, 'kairosoft-theme: styles');

      ctx.effect(() => {
        const rows = [];
        const controls = [
          ['panel', '面板不透明度', 60, 98, '%'],
          ['sidebar', '侧栏不透明度', 60, 98, '%'],
          ['focus', '背景取景位置', 0, 100, '%'],
        ];
        const fields = controls.map(([key, label, min, max, unit]) => {
          const out = el('output', { text: `${settings[key]}${unit}` });
          const input = el('input', {
            type: 'range',
            min: String(min),
            max: String(max),
            step: '1',
            value: String(settings[key]),
            oninput: (event) => {
              settings[key] = Number(event.target.value);
              out.textContent = `${settings[key]}${unit}`;
              writeSettings(settings);
              syncAll();
            },
          });
          const row = el('label', { className: 'kf-row' }, [
            el('span', { className: 'kf-head' }, [el('span', { text: label }), out]),
            input,
          ]);
          rows.push({ key, unit, input, out, row });
          return row;
        });

        const linkBox = el('input', {
          type: 'checkbox',
          onchange: (event) => {
            settings.linkSidebar = event.target.checked;
            writeSettings(settings);
            syncLink();
            syncTokens();
          },
        });
        linkBox.checked = settings.linkSidebar;

        function syncLink() {
          const row = rows.find((entry) => entry.key === 'sidebar');
          if (!row) return;
          row.input.disabled = Boolean(settings.linkSidebar);
          row.row.style.opacity = settings.linkSidebar ? '0.45' : '';
        }
        syncLink();

        const artworkBox = el('input', {
          type: 'checkbox',
          onchange: (event) => {
            settings.artwork = event.target.checked;
            writeSettings(settings);
            syncArtwork();
          },
        });
        artworkBox.checked = settings.artwork;

        const shadowBox = el('input', {
          type: 'checkbox',
          onchange: (event) => {
            settings.softShadow = event.target.checked;
            writeSettings(settings);
            syncShadow();
          },
        });
        shadowBox.checked = settings.softShadow;

        // Light / dark / system is the app's own appearance preference, so it
        // is driven through the theme service rather than through our tokens.
        const MODES = [
          ['light', '浅色'],
          ['dark', '深色'],
          ['system', '跟随系统'],
        ];
        const modeButtons = new Map();
        const readMode = () => {
          try {
            return ctx.theme.getTheme().preference ?? 'system';
          } catch {
            return 'system';
          }
        };
        const syncMode = () => {
          const active = readMode();
          for (const [id, button] of modeButtons) {
            button.setAttribute('aria-pressed', String(id === active));
          }
        };
        const modeRow = el(
          'div',
          { className: 'kf-themes' },
          MODES.map(([id, label]) => {
            const button = el('button', {
              className: 'kf-mode',
              type: 'button',
              text: label,
              onclick: () => {
                try {
                  ctx.theme.setTheme(id);
                } catch {
                  /* older runtime without setTheme: leave the app as it is */
                }
                syncMode();
                syncPanelColors();
              },
            });
            modeButtons.set(id, button);
            return button;
          }),
        );

        // Theme picker: one button per bundled theme plus the built-in palette.
        const themeButtons = new Map();
        const themeRow = el(
          'div',
          { className: 'kf-themes' },
          THEME_IDS.map((id) => {
            const button = el('button', {
              className: 'kf-theme',
              type: 'button',
              text: THEME_PACK[id].label.zh,
              onclick: () => chooseTheme(id),
            });
            themeButtons.set(id, button);
            return button;
          }).concat(
            (() => {
              const button = el('button', {
                className: 'kf-theme',
                type: 'button',
                text: '默认',
                onclick: () => chooseTheme(NATIVE),
              });
              themeButtons.set(NATIVE, button);
              return button;
            })(),
          ),
        );

        function syncTheme() {
          const current = settings.theme === undefined ? NATIVE : settings.theme;
          for (const [id, button] of themeButtons) {
            button.setAttribute('aria-pressed', String(id === current));
          }
          // The knobs only describe our palettes; on the built-in one they do
          // nothing, so they are greyed out instead of silently ignored.
          const off = !THEME_PACK[current];
          controlsBox.style.opacity = off ? '0.4' : '';
          controlsBox.style.pointerEvents = off ? 'none' : '';
          syncPanelColors();
        }

        function chooseTheme(id) {
          settings.theme = id;
          writeSettings(settings);
          syncTheme();
          syncAll();
        }

        const controlsBox = el('div', {}, [
          el('label', { className: 'kf-check' }, [artworkBox, el('span', { text: '显示背景图' })]),
          el('label', { className: 'kf-check' }, [linkBox, el('span', { text: '侧栏与主区同色' })]),
          el('label', { className: 'kf-check' }, [shadowBox, el('span', { text: '柔和阴影与底部渐隐' })]),
          ...fields,
        ]);

        const sheet = el('div', { className: 'kf-sheet', hidden: '' }, [
          el('h2', {}, [
            el('span', { text: 'Kairosoft 主题' }),
            el('button', {
              className: 'kf-close',
              type: 'button',
              text: '×',
              onclick: () => sheet.setAttribute('hidden', ''),
            }),
          ]),
          el('p', { className: 'kf-sub', text: '调整只影响本机，立即生效。' }),
          el('p', { className: 'kf-label', text: '主题' }),
          themeRow,
          el('p', { className: 'kf-label', text: '明暗' }),
          modeRow,
          controlsBox,
          el('div', { className: 'kf-foot' }, [
            el('button', {
              type: 'button',
              text: '恢复默认',
              onclick: () => {
                Object.assign(settings, DEFAULTS);
                writeSettings(settings);
                for (const row of rows) {
                  row.input.value = String(settings[row.key]);
                  row.out.textContent = `${settings[row.key]}${row.unit}`;
                }
                artworkBox.checked = settings.artwork;
                linkBox.checked = settings.linkSidebar;
                shadowBox.checked = settings.softShadow;
                syncLink();
                syncTheme();
                syncAll();
              },
            }),
            el('span', { className: 'kf-sub', style: 'margin:0', text: `v${__VERSION__}` }),
          ]),
        ]);

        const fab = el('button', {
          className: 'kf-fab',
          type: 'button',
          title: '主题设置',
          'aria-label': '主题设置',
          html: LANTERN,
          onclick: () => {
            if (sheet.hasAttribute('hidden')) sheet.removeAttribute('hidden');
            else sheet.setAttribute('hidden', '');
          },
        });

        // The panel's own palette: taken from the active theme, or from a
        // neutral fallback when the built-in palette is in charge.
        const UI_FALLBACK = {
          light: {
            panel: '#FCF7EA', raised: 'rgba(57,45,35,0.06)', text: '#392D23',
            muted: '#7A654B', line: 'rgba(57,45,35,0.16)', accent: '#AE4C18',
            onAccent: '#FFF6E2',
          },
          dark: {
            panel: '#1B2330', raised: 'rgba(242,231,206,0.08)', text: '#F2E7CE',
            muted: '#A4927A', line: 'rgba(242,231,206,0.18)', accent: '#F2A93B',
            onAccent: '#241A10',
          },
        };
        const prefersDark = () =>
          typeof matchMedia === 'function' && matchMedia('(prefers-color-scheme: dark)').matches;
        const isDarkMode = () => {
          const preference = readMode();
          if (preference === 'dark') return true;
          if (preference === 'light') return false;
          return prefersDark();
        };
        const syncPanelColors = () => {
          const pack = THEME_PACK[settings.theme];
          const table = (pack && pack.ui) || UI_FALLBACK;
          const ui = table[isDarkMode() ? 'dark' : 'light'];
          for (const node of [sheet, fab]) {
            node.style.setProperty('--kf-panel', ui.panel);
            node.style.setProperty('--kf-raised', ui.raised);
            node.style.setProperty('--kf-text', ui.text);
            node.style.setProperty('--kf-muted', ui.muted);
            node.style.setProperty('--kf-line', ui.line);
            node.style.setProperty('--kf-accent', ui.accent);
            node.style.setProperty('--kf-on-accent', ui.onAccent);
          }
        };

        document.body.append(fab, sheet);
        syncPanelColors();
        syncTheme();
        syncMode();
        if (typeof ctx.on === 'function') {
          ctx.on('theme/change', () => {
            syncMode();
            syncPanelColors();
          });
        }
        if (typeof matchMedia === 'function') {
          const media = matchMedia('(prefers-color-scheme: dark)');
          const onChange = () => syncPanelColors();
          if (typeof media.addEventListener === 'function') media.addEventListener('change', onChange);
          ctx.effect(
            () => () => {
              if (typeof media.removeEventListener === 'function') {
                media.removeEventListener('change', onChange);
              }
            },
            'kairosoft-theme: scheme listener',
          );
        }
        return () => {
          fab.remove();
          sheet.remove();
        };
      }, 'kairosoft-theme: panel');
    };

    return {
      inject: ['theme'],
      apply(ctx) {
        mount(ctx);
      },
    };
  },
});
